functions.template:
{%- set a1rw = http('https://verkehr.autobahn.de/o/autobahn/A1/services/roadworks') -%}
{%- set a7rw = http('https://verkehr.autobahn.de/o/autobahn/A7/services/roadworks') -%}
{%- set a20rw = http('https://verkehr.autobahn.de/o/autobahn/A20/services/roadworks') -%}
{%- set a24rw = http('https://verkehr.autobahn.de/o/autobahn/A24/services/roadworks') -%}
{%- set a25rw = http('https://verkehr.autobahn.de/o/autobahn/A25/services/roadworks') -%}
{%- set a1w = http('https://verkehr.autobahn.de/o/autobahn/A1/services/warning') -%}
{%- set a7w = http('https://verkehr.autobahn.de/o/autobahn/A7/services/warning') -%}
{%- set a20w = http('https://verkehr.autobahn.de/o/autobahn/A20/services/warning') -%}
{%- set a24w = http('https://verkehr.autobahn.de/o/autobahn/A24/services/warning') -%}
{%- set a25w = http('https://verkehr.autobahn.de/o/autobahn/A25/services/warning') -%}
{%- macro block(road, rw, w) -%}{% set lines %}{% for x in rw.roadworks %}{% if not x.future and x.coordinate and x.coordinate.lat >= 53.3 and x.coordinate.lat <= 53.95 and x.coordinate.long >= 9.75 and x.coordinate.long <= 10.8 %}Baustelle {{x.title}}{% if x.subtitle %} ({{x.subtitle | trim}}){% endif %}{% if x.isBlocked %} GESPERRT{% endif %}~~{% endif %}{% endfor %}{% for x in w.warning %}{% if x.coordinate and x.coordinate.lat >= 53.3 and x.coordinate.lat <= 53.95 and x.coordinate.long >= 9.75 and x.coordinate.long <= 10.8 %}Meldung {{x.title}}{% if x.subtitle %} ({{x.subtitle | trim}}){% endif %}{% if x.abnormalTrafficType == 'SLOW_TRAFFIC' %} angespannt{% elif x.abnormalTrafficType %} - {{x.abnormalTrafficType | replace('_',' ') | lower}}{% endif %}~~{% endif %}{% endfor %}{% endset %}{% set parts = lines.split('~~') | reject('equalto','') | list %}{% for p in parts %}{% if loop.index <= 3 %}
{{road}}: {{p}}{% endif %}{% endfor %}{%- endmacro -%}
{%- macro pick(road, rw, w) -%}{% if road == args.road or not args.road %}{{block(road, rw, w)}}{% endif %}{%- endmacro -%}
{%- set b1 = pick('A1', a1rw, a1w) -%}
{%- set b7 = pick('A7', a7rw, a7w) -%}
{%- set b20 = pick('A20', a20rw, a20w) -%}
{%- set b24 = pick('A24', a24rw, a24w) -%}
{%- set b25 = pick('A25', a25rw, a25w) -%}
{%- set hits = [b1, b7, b20, b24, b25] | reject('equalto','') | list -%}
{%- if hits | length > 0 -%}
{{hits | join('') | trim}}
{%- else -%}
Im Umland ist aktuell nichts gemeldet - alle Heimautobahnen frei.{% if args.road %} {{args.road}}{% endif %}
{%- endif -%}
